import React from "react";
import { useProductView } from "./useProductView";
import {
  Row,
  Col,
  Card,
  Label,
  Input,
  Button,
  CardImg,
  CardText,
  CardBody,
  CardTitle,
  FormGroup,
  CardSubtitle,
} from "reactstrap";

const ProductView = () => {
  const {
    product,
    getImage,
    selectedColor,
    selectedSize,
    selectedQuantity,
    setSelectedColor,
    setSelectedSize,
    handleQuantityChange,
    error,
  } = useProductView();

  if (error) {
    return <p>{error}</p>;
  }

  if (!product) {
    return <p>Loading product details...</p>;
  }

  const quantityOptions = Array.from(
    { length: Number(product.quantity) || 0 },
    (_, i) => i + 1
  );

  return (
    <Card className="product-details">
      <Row>
        <Col sm="12" md="4">
          <CardImg
            width="100%"
            src={`http://localhost:1337${getImage(selectedColor)}`}
            alt={product.name || "Product image"}
          />
        </Col>
        <Col sm="12" md="8">
          <CardBody>
            <CardTitle>{product.name}</CardTitle>
            <CardText>{product.description || "No description available."}</CardText>
            <CardSubtitle>
              <strong>Price: £{product.price}</strong>
            </CardSubtitle>
            <CardSubtitle>{product.quantity} items Left</CardSubtitle>
            <div>
              <CardSubtitle>Sizes:</CardSubtitle>
              <div className="sizes">
                {product.sizes.map((size) => (
                  <span
                    key={size.name}
                    className={`${selectedSize === size.name ? "active" : ""}`}
                    onClick={() => setSelectedSize(size.name)}
                  >
                    {size.name}
                  </span>
                ))}
              </div>
            </div>
            <div>
              <CardSubtitle>Selected Colour: {selectedColor}</CardSubtitle>
              <div className="colours">
                {product.color.map((colour) => (
                  <span
                    key={colour.name}
                    className={`${
                      selectedColor === colour.name ? "active" : ""
                    }`}
                    onClick={() => setSelectedColor(colour.name)}
                  >
                    <img
                      src={`http://localhost:1337${getImage(colour.name)}`}
                      alt={colour.name}
                    />
                  </span>
                ))}
              </div>
              <FormGroup className="quantity">
                <Label for="quantitySelect">Quantity</Label>
                <Input
                  value={selectedQuantity}
                  type="select"
                  name="quantity"
                  id="quantitySelect"
                  onChange={handleQuantityChange}
                >
                  {quantityOptions.map((number) => (
                    <option key={number} value={number}>
                      {number}
                    </option>
                  ))}
                </Input>
              </FormGroup>
            </div>
            <Button color="primary">Add to basket</Button>
          </CardBody>
        </Col>
      </Row>
    </Card>
  );
};

export default ProductView;
